39	func (codexImporter) Discover(repoRoot, overridePath string, now time.Time, sessionFilter []string) ([]SessionFile, error) {
40		dir, err := resolveDir(repoRoot, overridePath, "codex", (&codex.CodexAgent{}).GetSessionDir)
41		if err != nil {
42			return nil, err
43		}
44		cutoff := now.AddDate(0, 0, -LookbackDays)
45		var out []SessionFile
46		walkErr := filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
47			if err != nil {
48				if os.IsNotExist(err) {
49					return nil // missing root or vanished entry: nothing to import
50				}
51				return err
52			}
53			if d.IsDir() || !strings.HasSuffix(d.Name(), ".jsonl") {
54				return nil
55			}
56			info, statErr := d.Info()
57			if statErr != nil || info.ModTime().Before(cutoff) {
58				return nil //nolint:nilerr // skip unreadable/old entries, keep walking
59			}
60			meta, metaErr := codexReadSessionMeta(path)
61			if metaErr != nil || !repoMatches(meta.Cwd, repoRoot) {
62				return nil //nolint:nilerr // skip sessions we can't attribute to this repo
63			}
64			sessionID := meta.ID
65			if sessionID == "" {
66				sessionID = strings.TrimSuffix(d.Name(), ".jsonl")
67			}
68			if len(sessionFilter) > 0 && !slices.Contains(sessionFilter, sessionID) {
69				return nil
70			}
71			out = append(out, SessionFile{Path: path, SessionID: sessionID})
72			return nil
73		})
74		if walkErr != nil {
75			return nil, fmt.Errorf("walk codex sessions: %w", walkErr)
76		}
77		slices.SortFunc(out, func(a, b SessionFile) int { return strings.Compare(a.Path, b.Path) })
78		return out, nil
79	}
