12	// resolveDir returns overridePath when set, otherwise the agent's session
13	// directory for the repo. getDir is the agent's GetSessionDir method.
14	func resolveDir(repoRoot, overridePath, agentName string, getDir func(string) (string, error)) (string, error) {
15		if overridePath != "" {
16			return overridePath, nil
17		}
18		dir, err := getDir(repoRoot)
19		if err != nil {
20			return "", fmt.Errorf("resolve %s session dir: %w", agentName, err)
21		}
22		return dir, nil
23	}
