25	// sessionResolver maps a directory entry under dir to a discovered session's
26	// (sessionID, transcript path). ok=false skips the entry — it is not a
27	// transcript this importer should import (wrong extension/layout, or rejected
28	// by an importer-specific predicate such as a repo match).
29	type sessionResolver func(dir string, e os.DirEntry) (sessionID, path string, ok bool)
30	
31	// discoverSessionFiles lists transcripts in dir using the discovery rules every
32	// flat-directory importer shares: skip entries the resolver rejects, apply the
33	// session-ID filter, drop transcripts older than the lookback window (by the
34	// transcript file's modtime), and sort by path. A missing dir yields no
35	// sessions (not an error).
36	//
37	// codex does not use this — its sessions live in a recursively-walked,
38	// session_meta-filtered tree rather than a flat directory.
39	func discoverSessionFiles(dir string, now time.Time, sessionFilter []string, resolve sessionResolver) ([]SessionFile, error) {
40		entries, err := os.ReadDir(dir)
41		if err != nil {
42			if os.IsNotExist(err) {
43				return nil, nil
44			}
45			return nil, fmt.Errorf("read session dir: %w", err)
46		}
47		cutoff := now.AddDate(0, 0, -LookbackDays)
48		var out []SessionFile
49		for _, e := range entries {
50			sessionID, path, ok := resolve(dir, e)
51			if !ok {
52				continue
53			}
54			if len(sessionFilter) > 0 && !slices.Contains(sessionFilter, sessionID) {
55				continue
56			}
57			info, statErr := os.Stat(path)
58			if statErr != nil || info.ModTime().Before(cutoff) {
59				continue
60			}
61			out = append(out, SessionFile{Path: path, SessionID: sessionID})
62		}
63		slices.SortFunc(out, func(a, b SessionFile) int { return strings.Compare(a.Path, b.Path) })
64		return out, nil
65	}
