67	// identitySessionID uses the file stem verbatim as the session ID — the common
68	// case for agents that name transcripts <sessionID><ext>.
69	func identitySessionID(stem string) string { return stem }
70	
71	// jsonlSessionResolver returns a sessionResolver for the common flat layout:
72	// one <stem><ext> file per session. deriveID maps the file stem to the session
73	// ID (identity for most agents; pi derives a UUID suffix). Directories and
74	// non-matching extensions are skipped.
75	func jsonlSessionResolver(ext string, deriveID func(stem string) string) sessionResolver {
76		return func(dir string, e os.DirEntry) (string, string, bool) {
77			if e.IsDir() || !strings.HasSuffix(e.Name(), ext) {
78				return "", "", false
79			}
80			stem := strings.TrimSuffix(e.Name(), ext)
81			return deriveID(stem), filepath.Join(dir, e.Name()), true
82		}
83	}
