	// Not parallel: overrides seams and chdirs into a temp repo.
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	t.Chdir(dir)
	// No ENTIRE_TEST_TTY => CanPromptInteractively() is false (non-interactive),
	// e.g. a scripted or agent-driven enable.

	promptCalled := false
